import { requireVendor } from "@/lib/vendor-auth";
import { prisma } from "@/lib/db";
import { vendorEntitlement } from "@/lib/entitlements";
import { VendorBusinessProfile } from "@/components/vendor/business-profile";
export default async function Page() { const user = await requireVendor(); const [vendor, ent] = await Promise.all([prisma.vendor.findUniqueOrThrow({ where: { id: user.vendorId }, include: { galleries: { include: { images: { select: { id: true, url: true }, orderBy: { sortOrder: 'asc' } } }, orderBy: { sortOrder: 'asc' } }, services: { where: { active: true }, select: { id: true, slug: true, name: true, durationMin: true, basePriceKobo: true } } } }), vendorEntitlement(user.vendorId)]); return <VendorBusinessProfile initial={{ businessName: vendor.businessName, providerType: vendor.providerType, description: vendor.description, privatePhone: vendor.privatePhone || '', privateWhatsapp: vendor.privateWhatsapp || '', instagramUrl: vendor.instagramUrl || '', state: vendor.state, city: vendor.city, neighbourhood: vendor.neighbourhood, address: vendor.address, cancellationPolicy: vendor.cancellationPolicy, hoursJson: vendor.hoursJson }} slug={vendor.slug} coverUrl={vendor.coverUrl} logoUrl={vendor.logoUrl} images={vendor.galleries.flatMap(g => g.images)} services={vendor.services} verified={vendor.verificationStatus === 'verified'} publicContact={ent.publicDirectContact} rating={vendor.ratingAvg} reviewCount={vendor.reviewCount} applicationStatus={vendor.applicationStatus} visibility={vendor.visibility}/>; }
